import{_ as o,C as n,o as a,c as E,j as e,a as d,b as i,w as r,E as s,a2 as p,a3 as h}from"./chunks/framework.C51MRPOx.js";const C=JSON.parse('{"title":"vLLM 推理","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/vLLM推理.md","filePath":"LLM推理/vLLM推理.md","lastUpdated":null}'),A={name:"LLM推理/vLLM推理.md"};function B(b,t,m,L,c,f){const l=n("Mermaid");return a(),E("div",null,[t[1]||(t[1]=e("h1",{id:"vllm-推理",tabindex:"-1"},[d("vLLM 推理 "),e("a",{class:"header-anchor",href:"#vllm-推理","aria-label":'Permalink to "vLLM 推理"'},"​")],-1)),t[2]||(t[2]=e("blockquote",null,[e("p",null,"vLLM 是跑在显卡上的推理服务：权重负责计算，服务把多路对话收成一批、把算过的键值按块放在显存里，再通过 OpenAI 兼容接口把结果送出去。")],-1)),t[3]||(t[3]=e("h2",{id:"一轮请求里的两个阶段",tabindex:"-1"},[d("一轮请求里的两个阶段 "),e("a",{class:"header-anchor",href:"#一轮请求里的两个阶段","aria-label":'Permalink to "一轮请求里的两个阶段"'},"​")],-1)),t[4]||(t[4]=e("p",null,"一段提示进来后，计算分成两段：",-1)),(a(),i(p,null,{default:r(()=>[s(l,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20P%5B%22Prefill%3Cbr%2F%3E%E6%95%B4%E6%AE%B5%E6%8F%90%E7%A4%BA%E4%B8%80%E6%AC%A1%E7%AE%97%E5%AE%8C%EF%BC%8C%E5%90%83%E6%BB%A1%E7%AE%97%E5%8A%9B%22%5D%20--%3E%7C%22%E6%AF%8F%E4%B8%AA%20token%20%E7%9A%84%E9%94%AE%E5%80%BC%E7%95%99%E5%9C%A8%E6%98%BE%E5%AD%98%22%7C%20D%5B%22Decode%3Cbr%2F%3E%E4%B8%80%E6%AC%A1%E7%94%9F%E6%88%90%E4%B8%80%E4%B8%AA%E6%96%B0%20token%EF%BC%8C%E6%9B%B4%E5%90%83%E6%98%BE%E5%AD%98%E5%B8%A6%E5%AE%BD%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=h('<table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>瓶颈</th></tr></thead><tbody><tr><td>Prefill</td><td>整段提示一次算完，时间大致随提示长度上升</td><td>吃算力</td></tr><tr><td>Decode</td><td>一次只生成一个新 token，提示本身不用再算；对话逐字出现就是这段</td><td>吃显存带宽——每一步要把越来越长的键值读出来</td></tr></tbody></table><p>两段分开调度后，每一路对话不再独占整张卡直到说完。</p><h2 id="连续批处理" tabindex="-1">连续批处理 <a class="header-anchor" href="#连续批处理" aria-label="Permalink to &quot;连续批处理&quot;">​</a></h2><p>多路请求按「谁先说完谁退出」叠在同一批里：已在 decode 的请求留在批次中，新请求的 prefill 插进批次空隙，某一路生成结束立刻退出，空位交给排队的请求。</p><p>服务报出的吞吐，是一小段时间里所有请求合在一起处理的 token 数，和「一路对话独占显卡时每个字有多快」是两个数。引擎约每 10 秒打一行平均值，空闲时间也算在这 10 秒里；读这行时，要把它和单次请求的 prefill、decode 分开。</p><h2 id="分页注意力" tabindex="-1">分页注意力 <a class="header-anchor" href="#分页注意力" aria-label="Permalink to &quot;分页注意力&quot;">​</a></h2><p>键值如果按「每路请求预留到最大长度」来占显存，短对话会在显卡上留下长空洞，路数一多就装不下。分页注意力把键值切成固定大小的块：请求变长时再领一块，生成结束就把块还回去，长度不同的请求因此可以挤在同一张卡上。</p><p>单请求能占多少块，由上下文上限封顶——提示、系统说明和已经生成的 token 都算进这个上限，超过的请求会被拒绝。</p><h2 id="启动时要定的几件事" tabindex="-1">启动时要定的几件事 <a class="header-anchor" href="#启动时要定的几件事" aria-label="Permalink to &quot;启动时要定的几件事&quot;">​</a></h2><p>这些是服务的开关，换一张卡、换一个模型就重新选，不写进权重里。</p><table tabindex="0"><thead><tr><th>开关</th><th>决定什么</th></tr></thead><tbody><tr><td>显存占用比例</td><td>启动时向驱动申请显存的比例，用来放权重和键值块。比例高则键值块更多、能同时挂住的上下文更长；比例低则把余量留给同卡其他进程。权重先占掉一份固定大小，剩下的才是块</td></tr><tr><td>上下文上限</td><td>单请求的硬上限，也是这一路最多能领的块数；系统提示、工具说明、对话历史都算在里面</td></tr><tr><td>专家并行</td><td>混合专家模型每个 token 只激活一小部分专家，但显卡要装下全部专家权重。专家并行把专家拆到多张卡上；单卡拆开没有通信收益，开关关掉，多卡才用它摊开专家</td></tr><tr><td>只要语言模型</td><td>多模态权重常带着视觉编码器；文本服务可启动时不加载视觉部分，显存只留给语言模型和键值块</td></tr><tr><td>量化</td><td>4/8 比特量化压小权重体积，才能和键值块一起放进一张卡。它改变的是权重怎么存，不改变 prefill 和 decode 的调度方式</td></tr><tr><td>解析器</td><td>推理解析把思考段和正式回答拆开；工具调用解析把工具调用收成结构化请求。解析器要配对模型的输出格式，换模型族就换解析器</td></tr><tr><td>前缀缓存</td><td>打开后，相同的系统提示和工具说明可在下一次请求里复用已算过的键值块。缩短的是 prefill，decode 仍逐 token 生成</td></tr></tbody></table><p>采样参数和「是否输出思考」要写成当前版本直接认识的字段。有的版本会整段忽略请求里的 <code>extra_body</code>——参数只放在那里，引擎仍按自己的默认值跑。</p>',12))])}const k=o(A,[["render",B]]);export{C as __pageData,k as default};
